// One pair of paws carries one product from the basket to the belt.
window.CustomerMotion=class {
 constructor(scene){this.scene=scene;this.arms=document.createElementNS('http://www.w3.org/2000/svg','svg');this.arms.classList.add('cashier-arms','customer-arms');this.held=document.createElement('div');this.held.className='held-shopping customer-held-shopping';this.arms.setAttribute('aria-hidden','true');this.held.setAttribute('aria-hidden','true');scene.append(this.held,this.arms);this.reset();}
 reset(){this.index=-1;this.stage='rest';this.scene.classList.remove('customer-unloading');this.arms.style.display=this.held.style.display='none';}
 step(index,t,gentle){const source=document.getElementById('belt-items').children[index];if(!source)return;const o=this.scene.getBoundingClientRect(),c=document.getElementById('customer').getBoundingClientRect(),basket=document.getElementById('customer-basket').getBoundingClientRect(),belt=document.getElementById('belt-items').getBoundingClientRect(),r=source.getBoundingClientRect();const point=(x,y)=>({x:x-o.x,y:y-o.y}),start=point(basket.x+basket.width/2,basket.y+basket.height*.3),end=point(belt.x+belt.width*.14,r.y+r.height/2),lift={x:start.x,y:start.y-r.height*.8},shoulders=[point(c.x+c.width*.30,c.y+c.height*.76),point(c.x+c.width*.72,c.y+c.height*.76)];const mix=(a,b,v)=>{v=Math.max(0,Math.min(1,v));v=v*v*(3-2*v);return{x:a.x+(b.x-a.x)*v,y:a.y+(b.y-a.y)*v};};this.scene.classList.add('customer-unloading');if(index!==this.index){this.index=index;this.held.innerHTML=source.innerHTML;}this.stage=t<.2?'reach':t<.42?'lift':t<.8?'carry':'place';if(gentle){this.arms.style.display=this.held.style.display='none';return;}let item=t<.2?start:t<.42?mix(start,lift,(t-.2)/.22):mix(lift,end,(t-.42)/.38);this.held.style.display=t>=.2&&t<.8?'block':'none';this.held.style.width=r.width+'px';this.held.style.height=r.height+'px';this.held.style.left=item.x+'px';this.held.style.top=item.y+'px';this.held.style.transform=`translate(-50%,-50%) rotate(${Math.sin(Math.PI*Math.min(1,t/.8))*-8}deg)`;this.held.style.opacity='1';this.arms.style.display='block';this.arms.setAttribute('viewBox',`0 0 ${o.width} ${o.height}`);const bear=document.getElementById('customer').innerHTML.includes('#c28b5c'),skin=bear?'#c28b5c':'#fff8e9',size=Math.max(6,r.width*.14);this.arms.innerHTML=shoulders.map((s,i)=>{const rest={x:s.x+(i?10:-10),y:s.y+14},grip={x:item.x+(i?1:-1)*r.width*.27,y:item.y+r.height*.2};const p=t<.2?mix(rest,grip,t/.2):t>.8?mix(grip,rest,(t-.8)/.2):grip;return `<path d="M${s.x} ${s.y}Q${s.x} ${Math.max(s.y,p.y)+12} ${p.x} ${p.y}" fill="none" stroke="${skin}" stroke-width="${size*1.8}" stroke-linecap="round"/><circle cx="${p.x}" cy="${p.y}" r="${size}" fill="${skin}"/>`;}).join('');}
};
